1094	async function getProtectedMemberReason(
1095	  req: Request,
1096	  access: ReturnType<typeof accessService>,
1097	  companyId: string,
1098	  member: { principalId: string; principalType: string; membershipRole: string | null },
1099	  opts?: {
1100	    actorRole?: HumanCompanyMembershipRole | null;
1101	    instanceAdminUserIds?: ReadonlySet<string>;
1102	    operation?: "archive" | "update";
1103	  },
1104	): Promise<string | null> {
1105	  if (member.principalType !== "user") return "Only human company members can be removed.";
1106	  if (req.actor.type !== "board") return "Board access is required to remove members.";
1107	  if (member.principalId === req.actor.userId) return "You cannot remove yourself.";
1108	  const isTargetInstanceAdmin = opts?.instanceAdminUserIds
1109	    ? opts.instanceAdminUserIds.has(member.principalId)
1110	    : await access.isInstanceAdmin(member.principalId);
1111	  if (isTargetInstanceAdmin) {
1112	    return "Instance admins cannot be removed from company access.";
1113	  }
1114	
1115	  const targetRole = member.membershipRole
1116	    ? normalizeHumanRole(member.membershipRole, "operator")
1117	    : "operator";
1118	  if (opts?.operation === "archive") {
1119	    if (targetRole === "owner") return "Board owners cannot be removed from company access.";
1120	    if (targetRole === "admin") return "Company admins cannot be removed from company access.";
1121	  }
1122	
1123	  const actorRole = opts?.actorRole ?? await resolveActorHumanRole(req, access, companyId);
1124	  if (!actorRole) return "Only active company members can remove users.";
1125	  if (humanRoleRank[targetRole] >= humanRoleRank[actorRole]) {
1126	    return "You can only remove users below your company role.";
1127	  }
1128	
1129	  return null;
1130	}
